def calc(expr: str) -> int | str:
    class CalcError(Exception):
        pass

    n = len(expr)
    i = 0

    def skip() -> None:
        nonlocal i
        while i < n and expr[i] == " ":
            i += 1

    def trunc_div(a: int, b: int) -> int:
        if b == 0:
            raise CalcError
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q

    def parse_expr() -> int:
        nonlocal i
        left = parse_term()
        while True:
            skip()
            if i < n and expr[i] in "+-":
                op = expr[i]
                i += 1
                right = parse_term()
                left = left + right if op == "+" else left - right
            else:
                break
        return left

    def parse_term() -> int:
        nonlocal i
        left = parse_factor()
        while True:
            skip()
            if i < n and expr[i] in "*/%":
                op = expr[i]
                i += 1
                right = parse_factor()
                if op == "*":
                    left *= right
                else:
                    q = trunc_div(left, right)
                    left = q if op == "/" else left - right * q
            else:
                break
        return left

    def parse_factor() -> int:
        nonlocal i
        flips: list[bool] = []
        bases: list[int] = []
        while True:
            skip()
            neg = False
            while i < n and expr[i] == "-":
                neg = not neg
                i += 1
                skip()
            flips.append(neg)
            bases.append(parse_atom())
            skip()
            if i < n and expr[i] == "^":
                i += 1
                continue
            break
        val = -bases[-1] if flips[-1] else bases[-1]
        for k in range(len(bases) - 2, -1, -1):
            if val < 0:
                raise CalcError
            val = bases[k] ** val
            if flips[k]:
                val = -val
        return val

    def parse_atom() -> int:
        nonlocal i
        skip()
        if expr[i] == "(":
            i += 1
            val = parse_expr()
            skip()
            i += 1
            return val
        j = i
        while i < n and expr[i].isdigit():
            i += 1
        return int(expr[j:i])

    try:
        return parse_expr()
    except CalcError:
        return "error"
